1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	
9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const;
17	
18	// The six priced types are the domain, so they are derived from the premium
19	// table rather than restated: a type nobody prices cannot be insured. The
20	// unknown-type case (broomstick) is still a runtime error the tests will drive.
21	type ItemType = keyof typeof BASE_PREMIUMS;
22	
23	// Components (as opposed to main items) are the only things the block rule
24	// applies to, so the distinction has to be data, not a price coincidence.
25	// Typed as a set of ItemType so a component can never name an unpriced type.
26	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
27	
28	const PERCENT_WHOLE = 100;
29	
30	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
31	// floating-point error that shifts the spec's round-up in MHPCO's favour.
32	const percentOf = (percent: number, amount: number): number =>
33	  (amount * percent) / PERCENT_WHOLE;
34	
35	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
36	// round up, payouts (MHPCO pays) round down.
37	const roundPremiumInMHPCOsFavour = Math.ceil;
38	
39	export type ScenarioResult = { premium: number };
40	
41	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
42	// the surcharge and claim tests still to come). They are typed as optional so
43	// the scenarios the tests actually send typecheck, without pricing them.
44	type Item = {
45	  type: ItemType;
46	  material?: string;
47	  enchantment?: number;
48	  cursed?: boolean;
49	};
50	
51	type Step = { op: string; items: Item[] };
52	
53	// `customer` and `op` are likewise unread so far: the loyalty-discount and
54	// follow-up-contract tests will reach for them.
55	type Scenario = {
56	  customer: { yearsWithMHPCO: number };
57	  steps: Step[];
58	};
59	
60	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
61	
62	const sumBasePremiums = (items: Item[]): number =>
63	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
64	
65	// Groups of items that are "alike" — same type. The type is kept alongside the
66	// items because the block rule asks about it; recovering it from items[0] would
67	// make every reader re-derive that a group is non-empty and homogeneous.
68	type AlikeItems = { type: ItemType; items: Item[] };
69	
70	const groupByType = (items: Item[]): AlikeItems[] => {
71	  const groups = new Map<ItemType, Item[]>();
72	  for (const item of items) {
73	    const group = groups.get(item.type) ?? [];
74	    group.push(item);
75	    groups.set(item.type, group);
76	  }
77	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
78	};
79	
80	// A block is a discount on the components' combined base premium, not a flat
81	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
82	// 20 % stays visible as the rule it is.
83	const blockBasePremium = (items: Item[]): number => {
84	  const undiscounted = sumBasePremiums(items);
85	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
86	};
87	
88	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
89	// pile is never cheaper than the block it contains. Components only — three
90	// swords are three separate insurances, not a discounted building block.
91	const formsABlock = ({ type, items }: AlikeItems): boolean =>
92	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
93	
94	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
95	  formsABlock(alikeItems)
96	    ? blockBasePremium(alikeItems.items)
97	    : sumBasePremiums(alikeItems.items);
98	
99	// Priced per group of alike items rather than over the whole list, so 3 runes
100	// and 3 moonstones each form their own block.
101	const policyBasePremiumFor = (items: Item[]): number =>
102	  groupByType(items)
103	    .map(basePremiumForGroup)
104	    .reduce((total, groupPremium) => total + groupPremium, 0);
105	
106	// Each item-specific surcharge is a percentage of the affected item's OWN base
107	// premium, so the rule is expressed as that percentage and the condition that
108	// triggers it. Adding a rule means adding an entry here, not another branch.
109	const surchargeFor = (item: Item): number => {
110	  const base = basePremiumForItem(item);
111	  const curse = item.cursed ? percentOf(CURSE_SURCHARGE_PERCENT, base) : 0;
112	  const highEnchantment =
113	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
114	      ? percentOf(HIGH_ENCHANTMENT_SURCHARGE_PERCENT, base)
115	      : 0;
116	  return curse + highEnchantment;
117	};
118	
119	// Charged alongside the policy base premium — never folded into it, or the
120	// policy-wide modifiers would compound on top of them.
121	const itemSurchargesFor = (items: Item[]): number =>
122	  items.reduce((total, item) => total + surchargeFor(item), 0);
123	
124	const quoteFor = (items: Item[]): ScenarioResult => {
125	  const policyBasePremium = policyBasePremiumFor(items);
126	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
127	  const premium = roundPremiumInMHPCOsFavour(
128	    policyBasePremium + itemSurchargesFor(items) + firstInsuranceSurcharge + PROCESSING_FEE,
129	  );
130	  return { premium };
131	};
132	
133	// Every scenario so far holds exactly one quote step, so only the first is
134	// priced. The follow-up-contract discount test will drive priced-per-step.
135	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
136	  const [firstStep] = scenario.steps;
137	  return { results: [quoteFor(firstStep.items)] };
138	};
